
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { ArrowLeft, Location, Van, Memo, Money, CircleCheck } from '@element-plus/icons-vue'
import { orderApi } from '@/api'
import type { OrderDetail } from '@/types'
import { dateTime, money, orderStatusType } from '@/utils'
const route=useRoute();const router=useRouter();const order=ref<OrderDetail>();const load=async()=>order.value=await orderApi.detail(Number(route.params.id));onMounted(load)
const cancel=async()=>{if(!order.value)return;const {value}=await ElMessageBox.prompt('请输入取消原因','取消订单',{inputValidator:v=>v?true:'请输入取消原因',type:'warning'});await orderApi.cancel(order.value.id,value);await load()}
</script>
<template><div v-if="order" class="page-container order-detail"><button class="back-btn" @click="router.back()"><el-icon><ArrowLeft/></el-icon>返回订单列表</button><section class="order-status-hero"><div><span class="status-large" :class="order.orderStatus.toLowerCase()"><el-icon><CircleCheck/></el-icon></span><div><el-tag :type="orderStatusType(order.orderStatus)" round>{{order.orderStatusName}}</el-tag><h1>{{order.orderStatus==='COMPLETED'?'订单已完成':order.orderStatus==='CANCELED'?'订单已取消':'订单正在处理中'}}</h1><p>{{order.orderStatus==='DELIVERING'?'骑手已出发，请保持电话畅通。':order.orderStatus==='PENDING_ACCEPT'?'管理员将在确认后开始备货。':'订单状态更新会同步展示在下方时间线。'}}</p></div></div><div class="status-price"><span>应付金额</span><b>{{money(order.orderAmount)}}</b></div></section><div class="detail-layout"><main><section class="detail-block"><h2><el-icon><Location/></el-icon>配送地址</h2><p><b>{{order.receiverName}} {{order.receiverPhone}}</b></p><p>{{order.receiverAddress}}</p></section><section class="detail-block"><h2>商品明细</h2><article v-for="item in order.items" :key="item.id" class="item-line"><div class="item-img"><img v-if="item.medicineImage" :src="item.medicineImage"/><span v-else>药</span></div><div><b>{{item.medicineName}}</b><span>{{money(item.medicinePrice)}} × {{item.quantity}}</span></div><strong>{{money(item.subtotalAmount)}}</strong></article></section><section v-if="order.userRemark||order.adminRemark||order.cancelReason" class="detail-block"><h2><el-icon><Memo/></el-icon>订单备注</h2><p v-if="order.userRemark">用户备注：{{order.userRemark}}</p><p v-if="order.adminRemark">管理员备注：{{order.adminRemark}}</p><p v-if="order.cancelReason" class="cancel-reason">取消原因：{{order.cancelReason}}</p></section></main><aside><section v-if="order.riderName" class="detail-block rider-card"><h2><el-icon><Van/></el-icon>配送骑手</h2><div class="rider-avatar">骑</div><b>{{order.riderName}}</b><p>{{order.riderPhone}}</p></section><section class="detail-block timeline-card"><h2>订单动态</h2><el-timeline><el-timeline-item v-for="log in order.statusLogs" :key="log.id" :timestamp="dateTime(log.createTime)" :type="log.afterStatus==='CANCELED'?'danger':log.afterStatus==='COMPLETED'?'success':'primary'" hollow><b>{{log.afterStatusName}}</b><p v-if="log.remark">{{log.remark}}</p></el-timeline-item></el-timeline></section><section class="detail-block amount-card"><h2><el-icon><Money/></el-icon>费用明细</h2><div><span>商品总额</span><b>{{money(order.productAmount)}}</b></div><div><span>配送费</span><b>{{money(order.deliveryFee)}}</b></div><div class="amount-total"><span>应付金额</span><strong>{{money(order.orderAmount)}}</strong></div></section><el-button v-if="order.orderStatus==='PENDING_ACCEPT'" class="cancel-btn" type="danger" plain @click="cancel">取消订单</el-button></aside></div></div></template>
