ce-items:center;margin:0 auto 9px;font-size:20px}.rider-card>b{font-size:15px}.rider-card p{font-size:12px}.timeline-card :deep(.el-timeline-item__timestamp){font-size:11px}.timeline-card :deep(.el-timeline-item__content){font-size:13px}.timeline-card :deep(.el-timeline-item__content p){color:#8290a4;font-size:12px;margin:4px 0}.amount-card>div{display:flex;justify-content:space-between;margin:11px 0;color:#718198;font-size:13px}.amount-card b{color:#344054}.amount-total{padding-top:13px;margin-top:15px!important;border-top:1px dashed #dbe4ed;align-items:end}.amount-total strong{color:#ff6d2c;font-size:23px}.cancel-btn{width:100%;height:40px}@media(max-width:720px){.order-status-hero{padding:20px;align-items:flex-start;gap:8px}.status-price b{font-size:20px}.detail-layout{grid-template-columns:1fr}.detail-layout aside{display:contents}.timeline-card{order:2}.amount-card{order:3}.cancel-btn{order:4;margin-top:-5px}.order-status-hero h1{font-size:17px}}</style>
